import secrets

def after_restore(state,now,refresh,connect):
    # Work on a replacement object; the copied initialization state is not trusted.
    credential=refresh()
    if credential['expires']<=now:raise ValueError('refreshed credential expired')
    connection=connect()
    try:
        connection.sendall(b'PING\n')
        if connection.recv(64)!=b'PONG\n':raise ValueError('new connection unhealthy')
    except BaseException:
        connection.close()
        raise
    return {'environment_id':secrets.token_hex(24),'credential':dict(credential),'connection':connection}
