def ready_shards(shards,checkpoints):
    by_id={}
    for row in shards:
        ident=row['id']
        if not isinstance(ident,str) or not ident or ident in by_id:raise ValueError('unique shard IDs required')
        if row['state'] not in ('OPEN','CLOSED','EXPIRED'):raise ValueError('unknown shard state')
        if not isinstance(row['parents'],list) or len(row['parents'])>2 or len(set(row['parents']))!=len(row['parents']):raise ValueError('zero, one or two distinct parents')
        by_id[ident]=row
    if set(checkpoints)-set(by_id):raise ValueError('checkpoint has unknown shard')
    for ident,value in checkpoints.items():
        if value!='SHARD_END' and (not isinstance(value,str) or not value.isdecimal()):raise ValueError('explicit sequence or terminal checkpoint required')
        if value=='SHARD_END' and by_id[ident]['state']=='OPEN':raise ValueError('open shard cannot have terminal checkpoint')
    visiting=set();seen=set()
    def visit(ident):
        if ident in visiting:raise ValueError('cyclic lineage')
        if ident in seen:return
        visiting.add(ident)
        for parent in by_id[ident]['parents']:
            if parent not in by_id or by_id[parent]['state']=='OPEN':raise ValueError('missing or still open parent')
            visit(parent)
        visiting.remove(ident);seen.add(ident)
    for ident in by_id:visit(ident)
    if any(row['state']=='EXPIRED' and checkpoints.get(ident)!='SHARD_END' for ident,row in by_id.items()):raise ValueError('expired unread history requires external reconciliation')
    return sorted(ident for ident,row in by_id.items() if row['state']!='EXPIRED' and checkpoints.get(ident)!='SHARD_END'
                  and all(checkpoints.get(parent)=='SHARD_END' for parent in row['parents']))
